"""Extract four-frames, their ring and the two poles from reciprocal deletion certificates. No clock or pole labels used."""
from pathlib import Path
from itertools import combinations
import json
D=Path(__file__).resolve().parents[1]/'results';load=lambda f:json.loads((D/(f+'.json')).read_text());E=set(map(tuple,load('ramsey_37_dual_stars')['red_edges']));edge=lambda a,b:tuple(sorted((a,b))) in E;z={tuple(r['pair']):tuple(r['forced']) for r in load('ramsey_37_pair_regrowth_controls') if r['profiles']==2 and r['completions']==1 and len(r['forced'])==2};pairs=[(p,q) for p,q in z.items() if p<q and z.get(q)==p];B=[sorted(p+q) for p,q in pairs];assert len(set(sum(B,[])))==20 and len(B)==5 and all(not edge(*p) and not edge(*q) and all(edge(u,v) for u in p for v in q) for p,q in pairs);poles=sorted(set(range(22))-set(sum(B,[])));W=[[sum(edge(u,v) for u in b for v in c) if b!=c else 0 for c in B] for b in B];assert all(sorted(row)==[0,3,3,4,4] for row in W);assert edge(*poles) and all(sum(edge(p,v) for v in b)==1 for p in poles for b in B);out=dict(diagonals=pairs,frames=B,poles=poles,cross_red_counts=W);print(out);(D/'ramsey_37_reciprocal_regrowth_ring.json').write_text(json.dumps(out,indent=2)+'\n')
